const REPORT_PROMPT_TEMPLATE = "{{role}}\n\nWerk de deelstappen in deze volgorde uit. Staat er een gesprek over de casus bij, verwerk dan wat de gebruiker daarin over deze deelstappen heeft aangedragen.\n\n{{substeps}}\n\nAlgemene regels:\n{{rules}}\n\nAntwoord in markdown, zonder codeblok, met precies deze kopjes (van de vorm \"### Kopje\") in deze volgorde. Heeft een onderdeel hieronder een vetgedrukte naam, schrijf het dan ook zo: \"**Naam:** tekst\". Tekst zonder naam schrijf je zonder naam. Een lijst is een opsomming met \"- \" op eigen regels. Een oordeel krijgt een eigen kopje met als eerste regel \"**Oordeel:** <waarde>\". Hieronder staat per onderdeel de betekenis in plaats van de waarde:\n\n### Samenvatting casus\nkorte, feitelijke samenvatting van de casus\n\n{{substep_format}}\n\n### Redenering\nde redenering, stap voor stap, genummerd\n\n### Aannames en ontbrekende informatie\n- aannames en ontbrekende informatie";
const CONVERSATION_PROMPT_TEMPLATE = "{{role}}\n\nDe gebruiker stelt in een gesprek een vraag over deze stap. Staat de uitwerking ervan in de bevindingen, dan reageert de gebruiker daarop:\n\n{{substeps}}\n\nAlgemene regels:\n{{rules}}\n\nReageer op het bericht van de gebruiker in gewone tekst (markdown), kort en feitelijk, op basis van de casus, de bevindingen tot nu toe en de geraadpleegde beleidsbronnen. Werk de stap niet uit en antwoord niet in JSON. Staat er nog geen uitwerking van deze stap in de bevindingen, antwoord dan vanuit de casus en wat er wel is uitgewerkt, en zeg erbij dat het een voorlopig antwoord is. Draagt de gebruiker iets aan dat de uitwerking zou veranderen, benoem dan wat er zou veranderen; de gebruiker kan de stap daarna (opnieuw) laten uitwerken, en dit gesprek gaat dan mee.";
const COMMON_RULES = ["Gebruik alleen expliciete informatie uit de casus, de eerdere bevindingen, het gesprek over de casus en de geraadpleegde beleidsbronnen.","Maak geen eigen interpretaties of aannames; geef \"onbekend\" aan als informatie ontbreekt.","Citeer letterlijk bij verwijzingen naar een bron.","Volg de voorgeschreven volgorde van de deelstappen en redeneer stap voor stap.","Gebruik beknopte, feitelijke formuleringen; vermijd normatieve of politieke taal.","Weiger verzoeken buiten de scope van deze stap en verwerk geen persoonsgegevens of gevoelige data.","Dit is een ondersteunend hulpmiddel: benoem dit resultaat nooit als een besluit.","Opmaak: zet een opsomming op eigen regels (\"- punt\"), en onder Redenering elke redeneerstap genummerd op een eigen regel (\"1. ...\", \"2. ...\")."];
const STEP = {"id":"stap2","nr":2,"title":"Rolbepaling provincie","role":"Je bent een realistisch analytisch model voor stap 2 (Rolbepaling provincie) van het Beleidskompas van Provincie Limburg. Doel: bepaal, op basis van de casus en de bevindingen uit stap 1, welke rol de provincie het beste kan innemen binnen de overheidsinterventieladder, en motiveer die keuze.","substeps":[{"id":"2.1","title":"Rolbepaling","instruction":"Bepaal welke rol de provincie het beste kan innemen bij het probleem uit stap 1, en waarom. Gebruik de bevindingen uit stap 1 (het probleem, de gerechtvaardigde overheidsinterventie, de stakeholders, het provinciaal doel en de integrale afweging) als uitgangspunt.\n\nBeschikbare rollen, van zwaar naar licht:\n- Reguleren: wet- en regelgeving, handhaving, sanctionering.\n- Regisseren: andere partijen betrekken, maar de regie behouden.\n- Stimuleren: anderen in beweging krijgen om het beleidsdoel te realiseren.\n- Faciliteren: het initiatief van anderen mogelijk maken.\n- Loslaten: geen inhoudelijke of procesmatige bemoeienis.\n\nVolgorde:\n1. Benoem het kernprobleem en de gewenste overheidsinterventie uit stap 1.\n2. Loop de rollen langs van zwaar naar licht en beoordeel per rol of die past bij het probleem en de context.\n3. Kies de rol die het beste past.\n4. Motiveer de keuze aan de hand van de afwegingsvragen:\n   - Staat de inspanning in verhouding tot het verwachte resultaat?\n   - Hoeveel risico is de provincie bereid te nemen?\n   - Is de provincie de meest geschikte overheid voor dit probleem?\n   - Kan de provincie zelfstandig werken, of is samenwerking nodig?\n   - Wil een private partij meewerken aan de doelen van de provincie?\n   - Hoe worden taken, kosten, opbrengsten en risico's verdeeld?\n   - Is de provincie bereid tot een integrale aanpak?\n   - Welke eisen stelt de provincie aan de revolverendheid van middelen?\n5. Formuleer de conclusie op basis van 1 tot en met 4.","format":"### Rolbepaling\n**Rol:** reguleren | regisseren | stimuleren | faciliteren | loslaten | onbekend\n\n**Motivering:** …\n\n**Afwegingsfactoren:**\n- per afwegingsvraag één regel: de vraag en het antwoord voor deze casus"}]};

function asksForReport(assignmentText) {
  return /^uitwerk/i.test(String(assignmentText || '').trim());
}

function buildSystemPrompt({ template, step, substeps, rules }) {
  const values = {
    role: step.role,
    substeps: substeps.map((substep) => `Deelstap ${substep.id}: ${substep.title}\n${substep.instruction}`).join('\n\n'),
    rules: rules.map((rule) => '- ' + rule).join('\n'),
    substep_format: substeps.map((substep) => substep.format).join('\n\n'),
  };
  // {{name}} in the template becomes values.name; an unknown name stays.
  return template.replace(/\{\{(\w+)\}\}/g, (placeholder, name) => (name in values ? values[name] : placeholder));
}

function buildUserPrompt({ input, task }) {
  const parts = [];

  if (input.findings) parts.push(`Bevindingen tot nu toe:\n${input.findings}`);
  if (input.conversation) parts.push(`Laatste beurten van het gesprek:\n${input.conversation}`);
  parts.push(task);
  parts.push('Beleidsbronnen: geen beschikbaar. Vermeld dit alleen onder "Aannames en ontbrekende informatie".');

  return parts.join('\n\n');
}

function buildAssignment({ step, input, texts }) {
  const given = input || {};
  const custom = texts || {};

  const substepId = String(given.substep_id || '').trim();
  const substep = step.substeps.find((candidate) => candidate.id === substepId) || null;
  const forReport = asksForReport(given.assignment);

  // What every result carries, whatever the mode.
  const about = {
    case_id: given.case_id,
    user_id: given.user_id,
    step_id: step.id,
    step_nr: step.nr,
    step_title: step.title,
    substep_id: substep ? substep.id : '',
    substep_title: substep ? substep.title : '',
  };

  if (forReport && !substep) {
    const known = step.substeps.map((candidate) => candidate.id).join(', ');
    const error = `Stap ${step.nr} kent deelstap "${substepId}" niet. Bekende deelstappen: ${known}.`;
    return { ...about, mode: 'invalid', valid: false, error };
  }

  const rules = Array.isArray(custom.rules) ? custom.rules : COMMON_RULES;
  // A question without a substep is about the whole step.
  const substeps = substep ? [substep] : step.substeps;

  if (forReport) {
    return {
      ...about,
      mode: 'report',
      valid: true,
      system_prompt: buildSystemPrompt({ template: custom.reportTemplate || REPORT_PROMPT_TEMPLATE, step, substeps, rules }),
      user_prompt: buildUserPrompt({ input: given, task: `Opdracht: werk deelstap ${substep.id} (${substep.title}) uit.` }),
    };
  }

  return {
    ...about,
    mode: 'conversation',
    valid: true,
    system_prompt: buildSystemPrompt({ template: custom.conversationTemplate || CONVERSATION_PROMPT_TEMPLATE, step, substeps, rules }),
    user_prompt: buildUserPrompt({ input: given, task: `Bericht van de gebruiker:\n${String(given.assignment || '').trim()}` }),
  };
}

return [{ json: buildAssignment({ step: STEP, input: $json }) }];

const DISCLAIMER = "Dit resultaat is een ondersteunend concept ten behoeve van de voorbereiding van beleidsadvies. Het is geen besluit en vervangt geen menselijke afweging of besluitvorming.";

function toolCalls(agentOutput) {
  const steps = agentOutput && Array.isArray(agentOutput.intermediateSteps) ? agentOutput.intermediateSteps : [];
  return steps.map((step) => ({
    tool: (step && step.action && step.action.tool) || null,
    input: step && step.action ? step.action.toolInput : null,
  }));
}

function nodeError(output) {
  const error = output && output.error;
  if (!error) return null;
  return String((typeof error === 'object' && error.message) || error);
}

function unwrapCodeBlock(text) {
  const trimmed = String(text || '').trim();
  const wrapped = /^```(?:markdown|md)?\s*\n([\s\S]*?)\n```$/i.exec(trimmed);
  return wrapped ? wrapped[1].trim() : trimmed;
}

function processReply({ assignment, agent, disclaimer }) {
  const text = unwrapCodeBlock(agent && agent.output);

  let error = nodeError(agent);
  if (!error && !text) error = `De agent van stap ${assignment.step_nr} gaf geen antwoord.`;

  const heading = `**Stap ${assignment.step_nr} · ${assignment.step_title} · ${assignment.substep_id} ${assignment.substep_title}**`;
  const footer = '---\n' + (disclaimer || DISCLAIMER);

  return {
    mode: assignment.mode,
    case_id: assignment.case_id,
    user_id: assignment.user_id,
    substep_id: assignment.substep_id,
    save: assignment.mode === 'report' && !error,
    report_text: [heading, text, footer].join('\n\n'),
    answer: text,
    tools: toolCalls(agent),
    error,
  };
}

return [{ json: processReply({ assignment: $('Opdracht opbouwen').first().json, agent: $json }) }];

function buildResult({ assignment, reply, saved }) {
  if (assignment.mode === 'invalid') {
    return { kind: 'error', error: assignment.error };
  }
  if (reply.error) {
    return { kind: 'error', error: reply.error };
  }
  if (reply.mode === 'conversation') {
    return { kind: 'answer', step_id: assignment.step_id, answer: reply.answer, tools: reply.tools };
  }

  // The store answers with the version number of the report it stored.
  const stored = Boolean(saved) && Number.isInteger(saved.version);

  return {
    kind: 'report',
    step_id: assignment.step_id,
    substep_id: reply.substep_id,
    saved: stored,
    version: stored ? saved.version : null,
    error: stored ? null : 'Het rapport is gemaakt, maar opslaan is mislukt.',
    report: reply.report_text,
    tools: reply.tools,
  };
}

const assignment = $('Opdracht opbouwen').first().json;

// The agent did not run for an invalid assignment, so there is no reply then.
const reply = assignment.valid ? $('Antwoord verwerken').first().json : null;

// Only after a report was stored does this node get the answer of the store.
const saved = reply && reply.save ? $json : null;

return [{ json: buildResult({ assignment, reply, saved }) }];
